public class OrderProcessor {
    public void processOrders(List<Order> orders) {
        // Explicit type inference with diamond operator
        var filteredOrders = new ArrayList<Order>();

        for (var order : orders) {
            if (order.isUrgent()) {
                filteredOrders.add(order);
            }
        }

        // Stream API integration where types are verbose
        var orderSummaryMap = filteredOrders.stream()
            .collect(Collectors.groupingBy(Order::getCustomerId, Collectors.counting()));

        for (var entry : orderSummaryMap.entrySet()) {
            System.out.println("Customer: " + entry.getKey() + " Count: " + entry.getValue());
        }
    }
}
